'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { Mail, ArrowLeft, Loader2, CheckCircle2, AlertCircle, Store } from 'lucide-react';

export default function SellerForgotPasswordPage() {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) {
      setError('Please enter your registered seller email address.');
      return;
    }
    setError('');
    setLoading(true);

    try {
      // Send reset request
      await new Promise((resolve) => setTimeout(resolve, 1000));
      setSubmitted(true);
    } catch {
      setError('Could not process password reset. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-950 text-white flex flex-col justify-between relative overflow-hidden">
      {/* Top Header */}
      <header className="border-b border-white/10 bg-gray-900/50 backdrop-blur-md px-6 py-4 flex items-center justify-between z-20">
        <Link href="/" className="flex items-center gap-2 group">
          <div className="w-9 h-9 rounded-xl bg-primary flex items-center justify-center font-black text-gray-900 text-lg shadow-glow">
            Z
          </div>
          <span className="font-extrabold text-xl tracking-tight text-white">
            Zibon<span className="text-primary">baba</span>
          </span>
        </Link>
        <Link href="/seller/login" className="text-xs text-gray-400 hover:text-white flex items-center gap-1.5 transition-colors">
          <ArrowLeft size={14} /> Back to Seller Login
        </Link>
      </header>

      {/* Main Content */}
      <div className="flex-1 flex items-center justify-center px-4 py-12 relative z-10">
        <div className="w-full max-w-md">
          <div className="backdrop-blur-xl bg-white/5 border border-white/10 rounded-2xl p-6 sm:p-8 shadow-2xl">
            {submitted ? (
              <div className="text-center space-y-4">
                <div className="w-16 h-16 bg-green-500/20 text-green-400 border border-green-500/30 rounded-full flex items-center justify-center mx-auto">
                  <CheckCircle2 size={32} />
                </div>
                <h2 className="text-xl font-bold text-white">Check Your Email</h2>
                <p className="text-xs text-gray-400 leading-relaxed">
                  If an active seller account is associated with <span className="text-white font-medium">{email}</span>, we have sent instructions to reset your password.
                </p>
                <div className="pt-4">
                  <Link
                    href="/seller/login"
                    className="w-full inline-flex items-center justify-center gap-2 bg-primary hover:bg-primary-accent text-gray-950 font-bold py-2.5 rounded-lg text-xs transition-all"
                  >
                    Return to Seller Login
                  </Link>
                </div>
              </div>
            ) : (
              <div>
                <div className="mb-6">
                  <div className="w-12 h-12 rounded-xl bg-primary/20 border border-primary/40 flex items-center justify-center text-primary mb-3">
                    <Store size={24} />
                  </div>
                  <h2 className="text-xl font-bold text-white">Reset Seller Password</h2>
                  <p className="text-xs text-gray-400 mt-1">Enter your registered merchant email to receive a recovery link</p>
                </div>

                {error && (
                  <div className="flex items-start gap-2 bg-red-500/10 border border-red-500/30 text-red-400 rounded-lg p-3 mb-4 text-xs">
                    <AlertCircle size={16} className="shrink-0 mt-0.5" />
                    <span>{error}</span>
                  </div>
                )}

                <form onSubmit={handleSubmit} className="space-y-4">
                  <div>
                    <label className="block text-xs font-semibold text-gray-300 mb-1.5">
                      Seller Email Address
                    </label>
                    <div className="relative">
                      <Mail size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-500" />
                      <input
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="vendor@zibonbaba.com"
                        required
                        className="w-full bg-white/5 border border-white/10 text-white placeholder-gray-600 rounded-lg pl-10 pr-4 py-2.5 text-xs sm:text-sm focus:outline-none focus:ring-2 focus:ring-primary/50"
                      />
                    </div>
                  </div>

                  <button
                    type="submit"
                    disabled={loading}
                    className="w-full bg-primary hover:bg-primary-accent text-gray-950 font-extrabold py-3 rounded-lg transition-all shadow-glow disabled:opacity-60 flex items-center justify-center gap-2 text-xs sm:text-sm"
                  >
                    {loading ? (
                      <>
                        <Loader2 size={16} className="animate-spin" />
                        <span>Sending Recovery Email...</span>
                      </>
                    ) : (
                      <span>Send Recovery Link</span>
                    )}
                  </button>
                </form>

                <div className="mt-6 pt-4 border-t border-white/10 text-center">
                  <Link href="/seller/login" className="text-xs text-gray-400 hover:text-white transition-colors">
                    Back to Seller Login
                  </Link>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      <footer className="border-t border-white/10 bg-gray-950 py-4 text-center text-xs text-gray-600 z-10">
        © {new Date().getFullYear()} Zibonbaba Seller Center.
      </footer>
    </div>
  );
}

'use client';

import { useState } from 'react';
import {
  Building2,
  FileText,
  Landmark,
  ClipboardCheck,
  CheckCircle2,
  Clock,
  Upload,
  ChevronRight,
  AlertCircle,
  Shield,
} from 'lucide-react';

const steps = [
  { id: 1, label: 'Business Info', icon: Building2 },
  { id: 2, label: 'Tax & Legal', icon: FileText },
  { id: 3, label: 'Bank Account', icon: Landmark },
  { id: 4, label: 'Final Review', icon: ClipboardCheck },
];

const businessTypes = ['Sole Proprietorship', 'Partnership', 'Private Limited', 'Public Limited', 'NGO'];

export default function SellerKYCPage() {
  const [currentStep, setCurrentStep] = useState(2);
  const [completedSteps] = useState([1]);

  // Step 1 data (pre-filled / completed)
  const step1Data = {
    tradeLicense: 'TL-BD-2024-098374',
    businessType: 'Private Limited',
    registrationNumber: 'RJSC-2021-CLT-00882',
    tin: 'TIN-1234567890',
  };

  // Step 3 form state
  const [bankForm, setBankForm] = useState({
    bankName: '',
    accountName: '',
    accountNumber: '',
    branch: '',
    routing: '',
  });

  // File upload states
  const [nidFile, setNidFile] = useState<File | null>(null);
  const [licenseFile, setLicenseFile] = useState<File | null>(null);

  const handleDrop = (e: React.DragEvent, setter: (f: File) => void) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file) setter(file);
  };

  const overallStatus = 'Under Review';

  return (
    <div className="min-h-screen bg-gray-50 p-6 font-sans">
      {/* Header */}
      <div className="mb-8 flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-800">Store Verification</h1>
          <p className="text-gray-500 mt-1">Complete KYC verification to unlock full seller privileges.</p>
        </div>
        <div className="flex items-center gap-2 bg-yellow-100 border border-yellow-300 text-yellow-800 px-4 py-2 rounded-xl">
          <Clock size={16} className="text-yellow-600" />
          <span className="font-semibold text-sm">{overallStatus}</span>
        </div>
      </div>

      {/* Progress Tracker */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-6">
        <div className="flex items-center">
          {steps.map((step, index) => {
            const isCompleted = completedSteps.includes(step.id);
            const isCurrent = currentStep === step.id;
            return (
              <div key={step.id} className="flex items-center flex-1">
                <button
                  onClick={() => setCurrentStep(step.id)}
                  className="flex flex-col items-center gap-2 group"
                >
                  <div className={`w-11 h-11 rounded-xl flex items-center justify-center transition-all shadow-sm ${isCompleted ? 'bg-green-500 text-white' : isCurrent ? 'bg-[#FFC107] text-gray-900' : 'bg-gray-100 text-gray-400'}`}>
                    {isCompleted ? <CheckCircle2 size={20} /> : <step.icon size={20} />}
                  </div>
                  <span className={`text-xs font-semibold transition ${isCurrent ? 'text-gray-800' : isCompleted ? 'text-green-600' : 'text-gray-400'}`}>
                    {step.label}
                  </span>
                </button>
                {index < steps.length - 1 && (
                  <div className={`flex-1 h-0.5 mx-2 mb-5 ${completedSteps.includes(step.id) ? 'bg-green-400' : 'bg-gray-200'}`} />
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Step Content */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-6">

        {/* Step 1: Business Info (completed) */}
        {currentStep === 1 && (
          <div>
            <div className="flex items-center gap-2 mb-5">
              <CheckCircle2 size={20} className="text-green-500" />
              <h2 className="text-lg font-bold text-gray-800">Business Information</h2>
              <span className="ml-auto text-xs bg-green-100 text-green-700 px-2.5 py-1 rounded-full font-semibold">Completed</span>
            </div>
            <div className="grid grid-cols-2 gap-5">
              {[
                { label: 'Trade License Number', value: step1Data.tradeLicense },
                { label: 'Business Type', value: step1Data.businessType },
                { label: 'Registration Number', value: step1Data.registrationNumber },
                { label: 'TIN Number', value: step1Data.tin },
              ].map((f) => (
                <div key={f.label} className="bg-green-50 rounded-xl p-4 border border-green-100">
                  <p className="text-xs font-semibold text-green-700 mb-1">{f.label}</p>
                  <p className="text-sm font-medium text-gray-800">{f.value}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Step 2: Tax & Legal — File Uploads */}
        {currentStep === 2 && (
          <div>
            <h2 className="text-lg font-bold text-gray-800 mb-5 flex items-center gap-2">
              <FileText size={20} className="text-[#FFC107]" /> Tax & Legal Documents
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              {/* National ID Upload */}
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Upload National ID (NID)</label>
                <div
                  onDrop={(e) => handleDrop(e, setNidFile)}
                  onDragOver={(e) => e.preventDefault()}
                  className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center gap-3 cursor-pointer transition ${nidFile ? 'border-green-400 bg-green-50' : 'border-gray-300 bg-gray-50 hover:border-yellow-400 hover:bg-yellow-50'}`}
                  onClick={() => document.getElementById('nid-upload')?.click()}
                >
                  {nidFile ? (
                    <>
                      <CheckCircle2 size={32} className="text-green-500" />
                      <p className="text-sm font-medium text-green-700">{nidFile.name}</p>
                      <p className="text-xs text-green-600">File ready for upload</p>
                    </>
                  ) : (
                    <>
                      <Upload size={32} className="text-gray-400" />
                      <p className="text-sm font-medium text-gray-600">Drag & drop or click to browse</p>
                      <p className="text-xs text-gray-400">Supports JPG, PNG, PDF (max 5MB)</p>
                    </>
                  )}
                  <input id="nid-upload" type="file" className="hidden" accept=".jpg,.jpeg,.png,.pdf" onChange={(e) => e.target.files?.[0] && setNidFile(e.target.files[0])} />
                </div>
              </div>

              {/* Trade License Upload */}
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Upload Trade License</label>
                <div
                  onDrop={(e) => handleDrop(e, setLicenseFile)}
                  onDragOver={(e) => e.preventDefault()}
                  className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center gap-3 cursor-pointer transition ${licenseFile ? 'border-green-400 bg-green-50' : 'border-gray-300 bg-gray-50 hover:border-yellow-400 hover:bg-yellow-50'}`}
                  onClick={() => document.getElementById('license-upload')?.click()}
                >
                  {licenseFile ? (
                    <>
                      <CheckCircle2 size={32} className="text-green-500" />
                      <p className="text-sm font-medium text-green-700">{licenseFile.name}</p>
                      <p className="text-xs text-green-600">File ready for upload</p>
                    </>
                  ) : (
                    <>
                      <Upload size={32} className="text-gray-400" />
                      <p className="text-sm font-medium text-gray-600">Drag & drop or click to browse</p>
                      <p className="text-xs text-gray-400">Supports JPG, PNG, PDF (max 5MB)</p>
                    </>
                  )}
                  <input id="license-upload" type="file" className="hidden" accept=".jpg,.jpeg,.png,.pdf" onChange={(e) => e.target.files?.[0] && setLicenseFile(e.target.files[0])} />
                </div>
              </div>
            </div>
            <div className="mt-5 flex justify-end">
              <button
                onClick={() => setCurrentStep(3)}
                className="flex items-center gap-2 bg-[#FFC107] text-gray-900 font-semibold px-6 py-2.5 rounded-xl hover:bg-yellow-400 transition"
              >
                Continue <ChevronRight size={16} />
              </button>
            </div>
          </div>
        )}

        {/* Step 3: Bank Account */}
        {currentStep === 3 && (
          <div>
            <h2 className="text-lg font-bold text-gray-800 mb-5 flex items-center gap-2">
              <Landmark size={20} className="text-[#FFC107]" /> Bank Account Details
            </h2>
            <div className="grid grid-cols-2 gap-4">
              {[
                { key: 'bankName', label: 'Bank Name', placeholder: 'e.g. Dutch-Bangla Bank' },
                { key: 'accountName', label: 'Account Name', placeholder: 'e.g. ABC Store Ltd.' },
                { key: 'accountNumber', label: 'Account Number', placeholder: 'Enter account number' },
                { key: 'branch', label: 'Branch Name', placeholder: 'e.g. Gulshan Branch' },
                { key: 'routing', label: 'Routing Number', placeholder: 'Enter routing number' },
              ].map((f) => (
                <div key={f.key} className={f.key === 'routing' ? 'col-span-2 md:col-span-1' : ''}>
                  <label className="block text-xs font-semibold text-gray-600 mb-1.5">{f.label}</label>
                  <input
                    type="text"
                    placeholder={f.placeholder}
                    value={(bankForm as Record<string, string>)[f.key]}
                    onChange={(e) => setBankForm({ ...bankForm, [f.key]: e.target.value })}
                    className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm text-gray-700 bg-gray-50 focus:outline-none focus:ring-2 focus:ring-yellow-300"
                  />
                </div>
              ))}
            </div>
            <div className="mt-5 flex justify-end">
              <button
                onClick={() => setCurrentStep(4)}
                className="flex items-center gap-2 bg-[#FFC107] text-gray-900 font-semibold px-6 py-2.5 rounded-xl hover:bg-yellow-400 transition"
              >
                Continue <ChevronRight size={16} />
              </button>
            </div>
          </div>
        )}

        {/* Step 4: Final Review */}
        {currentStep === 4 && (
          <div>
            <h2 className="text-lg font-bold text-gray-800 mb-5 flex items-center gap-2">
              <ClipboardCheck size={20} className="text-[#FFC107]" /> Final Review & Submission
            </h2>

            {/* Review Summary */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
              <div className="bg-gray-50 rounded-xl p-4 border border-gray-100">
                <p className="text-xs font-bold text-gray-500 mb-2 uppercase tracking-wide">Business Info</p>
                <p className="text-sm text-gray-700">Trade License: {step1Data.tradeLicense}</p>
                <p className="text-sm text-gray-700">Type: {step1Data.businessType}</p>
                <p className="text-sm text-gray-700">TIN: {step1Data.tin}</p>
              </div>
              <div className="bg-gray-50 rounded-xl p-4 border border-gray-100">
                <p className="text-xs font-bold text-gray-500 mb-2 uppercase tracking-wide">Documents</p>
                <div className="flex items-center gap-2 text-sm">
                  {nidFile ? <CheckCircle2 size={14} className="text-green-500" /> : <AlertCircle size={14} className="text-orange-500" />}
                  <span className="text-gray-700">National ID: {nidFile ? nidFile.name : 'Not uploaded'}</span>
                </div>
                <div className="flex items-center gap-2 text-sm mt-1">
                  {licenseFile ? <CheckCircle2 size={14} className="text-green-500" /> : <AlertCircle size={14} className="text-orange-500" />}
                  <span className="text-gray-700">Trade License: {licenseFile ? licenseFile.name : 'Not uploaded'}</span>
                </div>
              </div>
            </div>

            {/* Submission Status */}
            <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-4 mb-5 flex items-start gap-3">
              <Shield size={20} className="text-yellow-600 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-semibold text-yellow-800">Application Status: Under Review</p>
                <p className="text-sm text-yellow-700 mt-1">Your KYC application is currently under review by our admin team. You will be notified via email once the verification is complete.</p>
              </div>
            </div>

            {/* Admin Notes */}
            <div className="border border-gray-200 rounded-xl p-4">
              <p className="text-sm font-semibold text-gray-700 mb-2 flex items-center gap-1.5">
                <FileText size={14} className="text-gray-400" /> Admin Notes
              </p>
              <p className="text-sm text-gray-400 italic">No notes from admin yet. Check back later.</p>
            </div>

            <div className="mt-5 flex justify-end">
              <button className="flex items-center gap-2 bg-gray-800 text-white font-semibold px-6 py-2.5 rounded-xl hover:bg-gray-700 transition">
                <CheckCircle2 size={16} /> Submit for Approval
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Step Navigation */}
      <div className="flex justify-between">
        <button
          onClick={() => setCurrentStep(Math.max(1, currentStep - 1))}
          disabled={currentStep === 1}
          className="px-5 py-2 rounded-xl border border-gray-200 text-gray-600 text-sm font-medium hover:bg-gray-50 transition disabled:opacity-30 disabled:cursor-not-allowed"
        >
          ← Previous
        </button>
        <div className="flex gap-2">
          {steps.map(s => (
            <button
              key={s.id}
              onClick={() => setCurrentStep(s.id)}
              className={`w-2.5 h-2.5 rounded-full transition ${currentStep === s.id ? 'bg-[#FFC107]' : completedSteps.includes(s.id) ? 'bg-green-400' : 'bg-gray-200'}`}
            />
          ))}
        </div>
        <button
          onClick={() => setCurrentStep(Math.min(4, currentStep + 1))}
          disabled={currentStep === 4}
          className="px-5 py-2 rounded-xl border border-gray-200 text-gray-600 text-sm font-medium hover:bg-gray-50 transition disabled:opacity-30 disabled:cursor-not-allowed"
        >
          Next →
        </button>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import {
  Users,
  UserCheck,
  Shield,
  Mail,
  Briefcase,
  Edit2,
  Trash2,
  UserPlus,
  X,
  Check,
  ChevronDown,
} from 'lucide-react';

const allPermissions = [
  'view:products',
  'edit:products',
  'view:orders',
  'manage:orders',
  'view:inventory',
  'manage:inventory',
  'view:reports',
];

const jobTitles = ['Store Manager', 'Inventory Staff', 'Sales Staff', 'Support Agent'];

const initialStaff = [
  {
    id: 1,
    name: 'Zara Khan',
    title: 'Inventory Staff',
    email: 'zara.khan@store.com',
    permissions: ['view:inventory', 'manage:inventory', 'view:products'],
    active: true,
  },
];

export default function SellerStaffPage() {
  const [staff, setStaff] = useState<any[]>(initialStaff);
  const [showInviteForm, setShowInviteForm] = useState(false);
  const [form, setForm] = useState({
    name: '',
    email: '',
    title: '',
    permissions: [] as string[],
  });
  const [formSent, setFormSent] = useState(false);

  useEffect(() => {
    const token = typeof window !== 'undefined' ? localStorage.getItem('zibonbaba_token') : null;
    if (token) {
      fetch('/api/seller/staff', { headers: { Authorization: `Bearer ${token}` } })
        .then(res => res.json())
        .then(data => {
          if (data.staff && Array.isArray(data.staff) && data.staff.length > 0) {
            setStaff(data.staff.map((s: any) => ({
              id: s.id,
              name: s.user?.profile?.fullName || s.user?.email || 'Staff Member',
              title: s.jobTitle || 'Staff',
              email: s.user?.email || 'staff@store.com',
              permissions: typeof s.permissions === 'string' ? JSON.parse(s.permissions) : (s.permissions || []),
              active: s.isActive ?? true
            })));
          }
        })
        .catch(() => {});
    }
  }, []);

  const togglePermission = (perm: string) => {
    setForm(prev => ({
      ...prev,
      permissions: prev.permissions.includes(perm)
        ? prev.permissions.filter(p => p !== perm)
        : [...prev.permissions, perm],
    }));
  };

  const toggleStaffActive = async (id: any) => {
    const target = staff.find(s => s.id === id);
    const newActive = !target?.active;
    setStaff(prev => prev.map(s => s.id === id ? { ...s, active: newActive } : s));

    const token = typeof window !== 'undefined' ? localStorage.getItem('zibonbaba_token') : null;
    if (token) {
      try {
        await fetch(`/api/seller/staff/${id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
          body: JSON.stringify({ isActive: newActive })
        });
      } catch (_) {}
    }
  };

  const removeStaff = async (id: any) => {
    setStaff(prev => prev.filter(s => s.id !== id));
    const token = typeof window !== 'undefined' ? localStorage.getItem('zibonbaba_token') : null;
    if (token) {
      try {
        await fetch(`/api/seller/staff/${id}`, {
          method: 'DELETE',
          headers: { Authorization: `Bearer ${token}` }
        });
      } catch (_) {}
    }
  };

  const handleInvite = async (e: React.FormEvent) => {
    e.preventDefault();
    const token = typeof window !== 'undefined' ? localStorage.getItem('zibonbaba_token') : null;
    if (token) {
      try {
        await fetch('/api/seller/staff', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
          body: JSON.stringify({
            email: form.email,
            fullName: form.name,
            jobTitle: form.title,
            permissions: form.permissions
          })
        });
      } catch (_) {}
    }

    const newStaff = {
      id: Date.now(),
      name: form.name,
      title: form.title,
      email: form.email,
      permissions: form.permissions,
      active: true,
    };
    setStaff(prev => [...prev, newStaff]);
    setForm({ name: '', email: '', title: '', permissions: [] });
    setFormSent(true);
    setTimeout(() => { setFormSent(false); setShowInviteForm(false); }, 2000);
  };

  const stats = [
    { label: 'Total Staff', value: staff.length.toString(), icon: Users, color: 'bg-purple-50 text-purple-600' },
    { label: 'Active', value: staff.filter(s => s.active).length.toString(), icon: UserCheck, color: 'bg-green-50 text-green-600' },
    { label: 'Roles', value: '3', icon: Briefcase, color: 'bg-yellow-50 text-yellow-600' },
  ];

  return (
    <div className="min-h-screen bg-gray-50 p-6 font-sans">
      {/* Header */}
      <div className="mb-8 flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-800">My Store Staff</h1>
          <p className="text-gray-500 mt-1">Manage your store team and their permissions.</p>
        </div>
        <button
          onClick={() => setShowInviteForm(true)}
          className="flex items-center gap-2 bg-[#FFC107] text-gray-900 font-semibold px-5 py-2.5 rounded-xl shadow hover:bg-yellow-400 transition"
        >
          <UserPlus size={16} /> Invite Staff Member
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-4 mb-6">
        {stats.map((s) => (
          <div key={s.label} className="bg-white rounded-xl shadow-sm border border-gray-100 p-5 flex items-center gap-4">
            <div className={`p-3 rounded-xl ${s.color}`}>
              <s.icon size={20} />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-800">{s.value}</p>
              <p className="text-sm text-gray-500">{s.label}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Available Roles Info */}
      <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-4 mb-6 flex items-center gap-4">
        <Shield size={20} className="text-yellow-600 flex-shrink-0" />
        <div>
          <p className="text-sm font-semibold text-yellow-800">Available Roles</p>
          <div className="flex flex-wrap gap-2 mt-1">
            {jobTitles.map(r => (
              <span key={r} className="text-xs bg-yellow-100 text-yellow-800 px-2.5 py-1 rounded-full font-medium border border-yellow-200">{r}</span>
            ))}
          </div>
        </div>
      </div>

      {/* Staff Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5 mb-8">
        {staff.map((member) => (
          <div key={member.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-5">
            <div className="flex items-start justify-between mb-4">
              <div className="flex items-center gap-3">
                <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-yellow-400 to-yellow-600 flex items-center justify-center text-white font-bold text-lg shadow">
                  {member.name.charAt(0)}
                </div>
                <div>
                  <p className="font-bold text-gray-800">{member.name}</p>
                  <p className="text-xs text-gray-500">{member.title}</p>
                </div>
              </div>
              {/* Status Toggle */}
              <button
                onClick={() => toggleStaffActive(member.id)}
                className={`relative w-11 h-6 rounded-full transition-colors ${member.active ? 'bg-green-500' : 'bg-gray-300'}`}
                title={member.active ? 'Deactivate' : 'Activate'}
              >
                <span className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow transition-all ${member.active ? 'left-6' : 'left-1'}`} />
              </button>
            </div>
            <div className="flex items-center gap-2 text-sm text-gray-500 mb-4">
              <Mail size={14} />
              <span className="truncate">{member.email}</span>
            </div>
            <div className="mb-4">
              <p className="text-xs font-semibold text-gray-500 mb-2">Permissions</p>
              <div className="flex flex-wrap gap-1.5">
                {(Array.isArray(member.permissions) ? member.permissions : []).map((p: string) => (
                  <span key={p} className="text-xs bg-yellow-100 text-yellow-800 border border-yellow-200 px-2 py-0.5 rounded-full font-medium">
                    {p}
                  </span>
                ))}
              </div>
            </div>
            <div className="flex gap-2 pt-3 border-t border-gray-100">
              <button className="flex-1 flex items-center justify-center gap-1.5 py-2 rounded-xl border border-gray-200 text-gray-600 text-xs font-semibold hover:bg-gray-50 transition">
                <Edit2 size={13} /> Edit
              </button>
              <button
                onClick={() => removeStaff(member.id)}
                className="flex-1 flex items-center justify-center gap-1.5 py-2 rounded-xl border border-red-100 text-red-500 text-xs font-semibold hover:bg-red-50 transition"
              >
                <Trash2 size={13} /> Remove
              </button>
            </div>
          </div>
        ))}

        {staff.length === 0 && (
          <div className="col-span-3 text-center py-16 text-gray-400">
            <Users size={40} className="mx-auto mb-3 opacity-30" />
            <p>No staff members yet. Invite someone to get started.</p>
          </div>
        )}
      </div>

      {/* Invite Form Modal */}
      {showInviteForm && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg p-6 relative">
            <button
              onClick={() => setShowInviteForm(false)}
              className="absolute top-4 right-4 text-gray-400 hover:text-gray-600 transition"
            >
              <X size={20} />
            </button>
            <h2 className="text-xl font-bold text-gray-800 mb-5 flex items-center gap-2">
              <UserPlus size={20} className="text-[#FFC107]" /> Invite Staff Member
            </h2>
            <form onSubmit={handleInvite} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-gray-600 mb-1.5">Full Name</label>
                  <input
                    type="text"
                    value={form.name}
                    onChange={(e) => setForm({ ...form, name: e.target.value })}
                    placeholder="e.g. John Doe"
                    className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm text-gray-700 bg-gray-50 focus:outline-none focus:ring-2 focus:ring-yellow-300"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-gray-600 mb-1.5">Email Address</label>
                  <input
                    type="email"
                    value={form.email}
                    onChange={(e) => setForm({ ...form, email: e.target.value })}
                    placeholder="email@example.com"
                    className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm text-gray-700 bg-gray-50 focus:outline-none focus:ring-2 focus:ring-yellow-300"
                    required
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs font-semibold text-gray-600 mb-1.5">Job Title</label>
                <div className="relative">
                  <select
                    value={form.title}
                    onChange={(e) => setForm({ ...form, title: e.target.value })}
                    className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm text-gray-700 bg-gray-50 focus:outline-none focus:ring-2 focus:ring-yellow-300 appearance-none"
                    required
                  >
                    <option value="">Select a job title</option>
                    {jobTitles.map(t => <option key={t}>{t}</option>)}
                  </select>
                  <ChevronDown size={14} className="absolute right-3 top-3.5 text-gray-400 pointer-events-none" />
                </div>
              </div>
              <div>
                <label className="block text-xs font-semibold text-gray-600 mb-2">Permissions</label>
                <div className="grid grid-cols-2 gap-2">
                  {allPermissions.map((perm) => {
                    const checked = form.permissions.includes(perm);
                    return (
                      <label
                        key={perm}
                        className={`flex items-center gap-2.5 cursor-pointer px-3 py-2 rounded-xl border transition ${checked ? 'bg-yellow-50 border-yellow-300' : 'bg-gray-50 border-gray-200 hover:border-gray-300'}`}
                      >
                        <div
                          onClick={() => togglePermission(perm)}
                          className={`w-4 h-4 rounded flex items-center justify-center border flex-shrink-0 transition ${checked ? 'bg-[#FFC107] border-yellow-500' : 'border-gray-300'}`}
                        >
                          {checked && <Check size={11} className="text-white font-bold" />}
                        </div>
                        <span className="text-xs font-medium text-gray-700">{perm}</span>
                      </label>
                    );
                  })}
                </div>
              </div>
              <button
                type="submit"
                className={`w-full py-3 rounded-xl font-semibold transition text-sm ${formSent ? 'bg-green-500 text-white' : 'bg-[#FFC107] text-gray-900 hover:bg-yellow-400'}`}
              >
                {formSent ? '✓ Invitation Sent!' : 'Send Invitation'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
